style.css:
/* Set custom cursor style */
* {
    cursor: url(https://cur.cursors-4u.net/nature/nat-10/nat1011.ani), 
            url(https://cur.cursors-4u.net/nature/nat-10/nat1011.gif), 
            auto !important;
}

/* Optional: Position the Fluttershy cursor image in the top-right corner */
body {
    position: relative;
}

body::after {
    content: url(https://cur.cursors-4u.net/cursor.png);
    position: absolute;
    top: 0;
    right: 0;
    z-index: 9999;
}

/* Link to Fluttershy My Little Pony page (this won't appear visually but will work if clicked) */
body::before {
    content: 'Fluttershy My Little Pony Cursor';
    position: absolute;
    top: 5px;
    right: 5px;
    font-size: 12px;
    color: #f0f0f0;
    background-color: rgba(0, 0, 0, 0.5);
    padding: 5px;
    border-radius: 5px;
    z-index: 9999;
    cursor: pointer;
}

body::before:hover {
    background-color: rgba(0, 0, 0, 0.7);
}
